def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each path moves only right or down from the top-left corner (1,1) to the bottom-right corner (N,N).
    A cell's value can be collected at most once, even if both paths pass through it.
    """
    # Build the grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # DP table: dp[i1][i2] = max sum when path1 is at (i1, j1) and path2 at (i2, j2)
    # where j1 = k - i1, j2 = k - i2 for current step k
    NEG_INF = -10**15
    dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # starting cell counted once

    # Iterate over steps from 3 to 2N (since step 2 corresponds to start)
    for k in range(3, 2 * N + 1):
        newdp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best_prev = NEG_INF
                # Consider all combinations of previous moves (up or left)
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        prev_val = dp[pi1][pi2]
                        if prev_val > best_prev:
                            best_prev = prev_val
                if best_prev == NEG_INF:
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                newdp[i1][i2] = best_prev + add
        dp = newdp

    return dp[N][N] if dp[N][N] != NEG_INF else 0

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Basic validation
    if M <= 0 or N <= 0:
        raise ValueError("M and N must be positive integers.")
    if K < 0 or K > M - 1:
        raise ValueError("K must be between 0 and M-1 inclusive.")
    if L < 0 or L > N - 1:
        raise ValueError("L must be between 0 and N-1 inclusive.")
    if D != len(chatting_pairs):
        raise ValueError("D does not match the number of provided chatting pairs.")
    for idx, pair in enumerate(chatting_pairs):
        if len(pair) != 4:
            raise ValueError(f"Chatting pair at index {idx} does not contain 4 coordinates.")
        x1, y1, x2, y2 = pair
        if not (1 <= x1 <= M and 1 <= x2 <= M and 1 <= y1 <= N and 1 <= y2 <= N):
            raise ValueError(f"Chatting pair at index {idx} contains out-of-bounds coordinates.")

    # Precompute which pairs are separated by each possible horizontal and vertical aisle
    row_sets = {r: set() for r in range(1, M)}   # aisle between row r and r+1
    col_sets = {c: set() for c in range(1, N)}   # aisle between column c and c+1

    for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
        # Horizontal separation
        if x1 < x2:
            for r in range(x1, x2):
                row_sets[r].add(idx)
        elif x2 < x1:
            for r in range(x2, x1):
                row_sets[r].add(idx)
        # Vertical separation
        if y1 < y2:
            for c in range(y1, y2):
                col_sets[c].add(idx)
        elif y2 < y1:
            for c in range(y2, y1):
                col_sets[c].add(idx)

    selected_rows = set()
    selected_cols = set()
    separated_pairs = set()

    # Greedy selection of aisles
    while len(selected_rows) < K or len(selected_cols) < L:
        best_gain = -1
        best_type = None  # 'row' or 'col'
        best_index = None

        # Evaluate rows
        if len(selected_rows) < K:
            for r in range(1, M):
                if r in selected_rows:
                    continue
                new_pairs = row_sets[r] - separated_pairs
                gain = len(new_pairs)
                if gain > best_gain or (gain == best_gain and best_type == 'col'):
                    best_gain = gain
                    best_type = 'row'
                    best_index = r

        # Evaluate columns
        if len(selected_cols) < L:
            for c in range(1, N):
                if c in selected_cols:
                    continue
                new_pairs = col_sets[c] - separated_pairs
                gain = len(new_pairs)
                if gain > best_gain or (gain == best_gain and best_type == 'row'):
                    best_gain = gain
                    best_type = 'col'
                    best_index = c

        # If no gain possible (all remaining aisles separate no new pairs), pick any remaining
        if best_index is None:
            if len(selected_rows) < K:
                for r in range(1, M):
                    if r not in selected_rows:
                        best_type = 'row'
                        best_index = r
                        break
            elif len(selected_cols) < L:
                for c in range(1, N):
                    if c not in selected_cols:
                        best_type = 'col'
                        best_index = c
                        break

        # Add the chosen aisle
        if best_type == 'row':
            selected_rows.add(best_index)
            separated_pairs.update(row_sets[best_index])
        else:
            selected_cols.add(best_index)
            separated_pairs.update(col_sets[best_index])

    # Prepare output strings
    row_str = ' '.join(str(r) for r in sorted(selected_rows))
    col_str = ' '.join(str(c) for c in sorted(selected_cols))

    return (row_str, col_str)

