def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    # Validate inputs
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(coeffs, (list, tuple)):
        raise TypeError("coeffs must be a list or tuple")
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n+1")
    for c in coeffs:
        if not isinstance(c, int):
            raise TypeError("All coefficients must be integers")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)

        # Variable part
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps if possible, otherwise "NO ANSWER!".
    """
    if A == B:
        return 0

    queue = [(A, 0)]
    visited = {A}

    while queue:
        current, steps = queue.pop(0)
        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is represented
                                as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.

    Raises:
        TypeError: If the input types are incorrect.
        ValueError: If the input values are invalid (e.g., negative number, digits out of range).
    """
    # Validate n
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    # Validate rules
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise TypeError("each rule must be a tuple of two integers")
        x, y = rule
        if not (isinstance(x, int) and isinstance(y, int)):
            raise TypeError("rule elements must be integers")
        if not (0 <= x <= 9 and 0 <= y <= 9):
            raise ValueError("rule digits must be between 0 and 9 inclusive")

    # Build mapping from digit to list of possible replacements
    mapping = {}
    for x, y in rules:
        mapping.setdefault(x, []).append(y)

    visited = {n}
    queue = [n]
    idx = 0

    while idx < len(queue):
        current = queue[idx]
        idx += 1
        s = str(current)
        for i, ch in enumerate(s):
            d = int(ch)
            if d in mapping:
                for target in mapping[d]:
                    new_s = s[:i] + str(target) + s[i+1:]
                    new_n = int(new_s)
                    if new_n not in visited:
                        visited.add(new_n)
                        queue.append(new_n)

    return len(visited)

